// Generated by Codex
package grading.execution;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * One student's graded questions, in assessment order.
 *
 * @param username  the student
 * @param questions the result of each question part
 */
public record StudentGradingResult(String username, List<QuestionGradingResult> questions) {

    public StudentGradingResult {
        questions = List.copyOf(questions);
    }

    /** True when any question could not be graded normally, so a person should look at it. */
    public boolean needsReview() {
        return questions.stream().anyMatch(question -> question.status() != QuestionGradingResult.Status.GRADED);
    }

    /** The student's marks over every question part. */
    public double totalScore() {
        return questions.stream().mapToDouble(QuestionGradingResult::score).sum();
    }

    /** The marks per question, with the parts of a question added up: Q1a and Q1b count as Q1. */
    public Map<String, Double> questionScores() {
        Map<String, Double> scores = new LinkedHashMap<>();
        for (QuestionGradingResult question : questions) {
            String group = question.questionId().replaceFirst("(?<=\\d)[a-z]+$", "");
            scores.merge(group, question.score(), Double::sum);
        }
        return Collections.unmodifiableMap(scores);
    }
}
